import ReactMarkdown from "react-markdown";
import type { RichSectionData } from "../block-zone/types";
import {
  DEFAULT_RICH_ASPECT,
  OFFER_CTA_DEFAULT,
  imageAspectClass,
  imageFitClass,
  imageFrameClass,
  resolveRichFondo,
  resolveRichImageSide,
  resolveRichMode,
  resolveRichMovimiento,
  resolveRichVideoUrl,
  richSectionHeadingClass,
  safeHref,
  BLOCK_RADIUS_BUTTON_CLASS,
  BLOCK_RADIUS_CLASS,
  BLOCK_RADIUS_THUMB_CLASS,
  SECTION_ROOT_CLASS,
} from "../block-zone/types";
import HeroFondoVideo from "./hero-fondo-video";
import RichMarquee from "./marquee";

type RichSectionProps = {
  data: RichSectionData;
  isOwner?: boolean;
};

// Botón de acción compartido por el CTA propio (`cta_url`) y el de la oferta (#4599).
const CTA_LINK_CLASS = `inline-flex items-center justify-center ${BLOCK_RADIUS_BUTTON_CLASS} border border-primary bg-transparent px-6 py-3 text-sm font-medium text-primary transition-colors duration-200 hover:bg-primary hover:text-primary-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary motion-reduce:transition-none`;

function RichSectionPlaceholder() {
  return (
    <section
      aria-label="Sección de texto"
      className={SECTION_ROOT_CLASS}
    >
      <div className={`${BLOCK_RADIUS_CLASS} border border-border bg-card px-8 py-12 text-center`}>
        <p className="font-heading text-sm text-muted-foreground">
          Sección de texto — agregá el contenido por chat
        </p>
      </div>
    </section>
  );
}

export default function RichSection({
  data,
  isOwner = false,
}: RichSectionProps) {
  // Banda marquee (#4284): el title es el texto; body/CTA/media quedan en data sin render.
  // Sin title no hay banda vacía: cae al render normal.
  const marqueeText = typeof data.title === "string" ? data.title.trim() : "";
  if (resolveRichMovimiento(data.movimiento) === "marquee" && marqueeText) {
    return <RichMarquee text={marqueeText} label={marqueeText} />;
  }

  // Kit-once (#3883): fuera del closed-set → default, nunca explota.
  const imageSide = resolveRichImageSide(data.image_side);
  const mode = resolveRichMode(data.mode);
  const isCenter = data.align === "center";
  const isChecklist = mode === "checklist";
  const isCenteredMode = mode === "centrado";
  const ctaHref = safeHref(data.cta_url);
  const imageUrl =
    typeof data.image_url === "string" && data.image_url.trim()
      ? data.image_url.trim()
      : undefined;
  const hasImage = Boolean(imageUrl);
  // Fondo completo (#4567): solo con media de fondo (imagen o video). Sin media → render normal.
  const videoUrl = resolveRichVideoUrl(data.video_url);
  // #4580: `completo` no admite botón (el dato se conserva, solo no se renderiza).
  const isCompleto = resolveRichFondo(data.fondo) === "completo";
  const isHero = isCompleto && (hasImage || Boolean(videoUrl));
  const splitLayout = hasImage && !isCenteredMode;
  // En hero el texto va sobre el overlay: centrado por `align`, aunque haya imagen.
  const textCentered = isCenter && (!hasImage || isHero);

  // Oferta viva (#4599): el kit solo pinta lo que el host resolvió; sin datos útiles, no renderiza nada.
  const offer = data.offer ?? null;
  const offerName = typeof offer?.name === "string" ? offer.name.trim() : "";
  const offerPrice = typeof offer?.priceLabel === "string" ? offer.priceLabel.trim() : "";
  const offerImageUrl =
    typeof offer?.imageUrl === "string" && offer.imageUrl.trim()
      ? offer.imageUrl.trim()
      : undefined;
  const offerHref = offer ? safeHref(offer.href) : undefined;
  const offerCtaLabel = offer
    ? (offer.ctaLabel ?? OFFER_CTA_DEFAULT).trim()
    : "";
  const offerNameClass = isHero ? "text-background" : "text-foreground";
  const offerPriceClass = isHero ? "text-background" : "text-muted-foreground";
  // #4580: `completo` no admite botón; la oferta tampoco lo renderiza ahí.
  const showOfferCta = Boolean(offerHref && offerCtaLabel && !isCompleto);
  const showOffer = Boolean(
    offerImageUrl || offerName || offerPrice || showOfferCta,
  );

  // Sin texto propio ni oferta que pintar: nada que renderizar (placeholder al owner).
  // Va después de `showOffer` para consultar el mismo predicado que el pintado de la oferta (#4604).
  if (!data.title && !data.body && !showOffer) {
    return isOwner ? <RichSectionPlaceholder /> : null;
  }

  // Tokens del cuerpo: default byte-idénticos a hoy; hero = tono inverso sobre el overlay.
  const bodyToneClass = isHero
    ? "max-w-none text-base leading-relaxed text-background break-words [&_a]:text-background [&_a]:underline [&_a]:underline-offset-4 [&_a:hover]:opacity-80 [&_strong]:font-semibold [&_strong]:text-background [&_h3]:font-heading [&_h3]:font-semibold [&_h3]:text-background"
    : "max-w-none text-base leading-relaxed text-muted-foreground break-words [&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4 [&_a:hover]:opacity-80 [&_strong]:font-semibold [&_strong]:text-foreground [&_h3]:font-heading [&_h3]:font-semibold [&_h3]:text-foreground";

  const text = (
    <div
      className={[
        "flex min-w-0 flex-col gap-6",
        textCentered ? "items-center text-center" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {data.title ? (
        <h2 className={richSectionHeadingClass(data, isHero ? "inverse" : "default")}>
          {data.title}
        </h2>
      ) : null}

      {data.body ? (
        <div
          className={[
            bodyToneClass,
            isChecklist
              ? [
                  "[&_ul]:list-none [&_ul]:space-y-3 [&_ul]:pl-0",
                  "[&_ol]:list-decimal [&_ol]:pl-5",
                  "[&_li]:relative [&_li]:pl-7",
                  "[&_li]:before:absolute [&_li]:before:left-0 [&_li]:before:top-1.5",
                  "[&_li]:before:size-4 [&_li]:before:rounded-[var(--block-radius-suave,0.125rem)]",
                  "[&_li]:before:border [&_li]:before:border-primary",
                  "[&_li]:before:bg-primary [&_li]:before:content-['']",
                ].join(" ")
              : isHero
                ? "[&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_li]:marker:text-background"
                : "[&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_li]:marker:text-primary",
            "[&_blockquote]:border-l-2 [&_blockquote]:border-border [&_blockquote]:pl-4 [&_blockquote]:italic",
            textCentered ? "mx-auto" : "",
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <ReactMarkdown>{data.body}</ReactMarkdown>
        </div>
      ) : null}

      {showOffer ? (
        <div className="flex flex-col gap-4">
          {offerImageUrl ? (
            <div
              className={[
                "relative aspect-square w-40 overflow-hidden sm:w-48",
                BLOCK_RADIUS_THUMB_CLASS,
                "bg-card",
              ].join(" ")}
            >
              <img
                src={offerImageUrl}
                alt={offerName}
                width={800}
                height={800}
                loading="lazy"
                decoding="async"
                className="size-full object-cover"
              />
            </div>
          ) : null}

          {offerName ? (
            <h3 className={`font-heading text-lg font-semibold ${offerNameClass}`}>
              {offerName}
            </h3>
          ) : null}

          {offerPrice ? (
            <p className={`text-base font-medium ${offerPriceClass}`}>
              {offerPrice}
            </p>
          ) : null}

          {showOfferCta ? (
            <div className={textCentered ? "flex justify-center" : undefined}>
              <a href={offerHref} className={CTA_LINK_CLASS}>
                {offerCtaLabel}
              </a>
            </div>
          ) : null}
        </div>
      ) : null}

      {ctaHref && data.cta_label && !isCompleto ? (
        <div
          className={textCentered ? "flex justify-center" : undefined}
        >
          <a
            href={ctaHref}
            className={CTA_LINK_CLASS}
          >
            {data.cta_label}
          </a>
        </div>
      ) : null}
    </div>
  );

  if (isHero) {
    return (
      <HeroFondoVideo
        label={data.title ?? "Sección de contenido"}
        imageUrl={imageUrl}
        videoUrl={videoUrl}
      >
        {text}
      </HeroFondoVideo>
    );
  }

  const image =
    hasImage && imageUrl ? (
      <div
        className={[
          "relative",
          imageAspectClass(data, DEFAULT_RICH_ASPECT),
          "w-full overflow-hidden",
          BLOCK_RADIUS_CLASS,
          imageFrameClass(data),
          "bg-card",
        ]
          .filter(Boolean)
          .join(" ")}
      >
        <img
          src={imageUrl}
          alt={data.title ? `Imagen: ${data.title}` : "Imagen de la sección"}
          width={800}
          height={1000}
          loading="lazy"
          decoding="async"
          className={["size-full", imageFitClass(data)].join(" ")}
        />
      </div>
    ) : null;

  return (
    <section
      aria-label={data.title ?? "Sección de contenido"}
      className={SECTION_ROOT_CLASS}
    >
      <div
        className={
          splitLayout
            ? "grid gap-10 md:grid-cols-2 md:items-center md:gap-14"
            : hasImage
              ? "grid gap-10"
              : undefined
        }
      >
        {splitLayout && imageSide === "left" ? (
          <>
            {image}
            {text}
          </>
        ) : (
          <>
            {text}
            {image}
          </>
        )}
      </div>
    </section>
  );
}

import type { ReactNode } from "react";
import { SECTION_ROOT_CLASS } from "../block-zone/types";

type HeroFondoVideoProps = {
  label: string;
  imageUrl?: string;
  videoUrl?: string;
  children: ReactNode;
};

/**
 * RichSection `fondo: completo` (#4567, hijo C de #4280). Full-bleed con media de fondo:
 * imagen (decorativa, `alt=""` + `aria-hidden`), `<video>` opcional encima (decorativo, sin
 * controles, muted/loop) y overlay fijo `bg-foreground/60`. El texto va en `children` con tono
 * inverso (`text-background`) para mantener AA sobre el overlay.
 * Fallback: sin video, o video que no carga, o reduce-motion → queda la imagen de fondo.
 * Solo video (sin imagen): la raíz lleva `bg-foreground` como base sólida; con reduce-motion o
 * video caído queda el overlay sobre ese color (texto inverso sigue en AA), no sobre el fondo
 * de página. Con imagen cargada, la imagen cubre el 100% y esa base no se ve; mientras la imagen
 * no carga (`loading="lazy"`) o si la URL falla, se ve `bg-foreground` bajo el overlay.
 * El caller solo lo usa si hay al menos imagen o video (sin media → render normal).
 */
export default function HeroFondoVideo({
  label,
  imageUrl,
  videoUrl,
  children,
}: HeroFondoVideoProps) {
  const isWebm = videoUrl
    ? new URL(videoUrl).pathname.toLowerCase().endsWith(".webm")
    : false;

  return (
    <section aria-label={label} className="relative w-full overflow-hidden bg-foreground">
      {imageUrl ? (
        <img
          src={imageUrl}
          alt=""
          aria-hidden="true"
          loading="lazy"
          decoding="async"
          className="absolute inset-0 size-full object-cover"
        />
      ) : null}

      {videoUrl ? (
        <video
          aria-hidden="true"
          autoPlay
          muted
          loop
          playsInline
          preload="metadata"
          poster={imageUrl}
          className="absolute inset-0 size-full object-cover motion-reduce:hidden"
        >
          <source src={videoUrl} type={isWebm ? "video/webm" : "video/mp4"} />
        </video>
      ) : null}

      <div className="absolute inset-0 bg-foreground/60" />

      <div className={`relative text-background ${SECTION_ROOT_CLASS}`}>
        {children}
      </div>
    </section>
  );
}

"use client";

type RichMarqueeProps = {
  text: string;
  label: string;
};

// Loop CSS puro (#4284): sin JS ni matchMedia en render, así SSR e hidratación coinciden.
// Velocidad fija: 30 s por vuelta (no hay prop de velocidad). Track = dos grupos idénticos;
// el loop mueve 50% = un grupo, así el salto es invisible.
// Reduced-motion vive acá (no en el globals.css del template): sin animación, el segundo grupo
// se oculta y el primero muestra el texto completo con wrap (sin recorte ni duplicado).
const MARQUEE_CSS = `
@keyframes guaso-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.guaso-marquee-track {
  display: flex;
  width: max-content;
  animation: guaso-marquee 30s linear infinite;
}
.guaso-marquee-group {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  padding-right: 3rem;
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .guaso-marquee-track {
    width: 100%;
    animation: none;
  }
  .guaso-marquee-group {
    flex-shrink: 1;
    min-width: 0;
    padding-right: 0;
    white-space: normal;
  }
  .guaso-marquee-group[aria-hidden="true"] {
    display: none;
  }
}
`;

/**
 * RichSection `movimiento: marquee` (#4284). Banda de una línea con el `title` como texto.
 * Sin botón Pausar (follow-up WCAG 2.2.2). Colores solo por tokens.
 */
export default function RichMarquee({ text, label }: RichMarqueeProps) {
  return (
    <section
      aria-label={label}
      className="w-full overflow-hidden bg-primary py-4 text-primary-foreground"
    >
      <style>{MARQUEE_CSS}</style>
      <div className="guaso-marquee-track">
        <div className="guaso-marquee-group font-heading text-2xl font-semibold tracking-tight">
          {text}
        </div>
        <div
          aria-hidden="true"
          className="guaso-marquee-group font-heading text-2xl font-semibold tracking-tight"
        >
          {text}
        </div>
      </div>
    </section>
  );
}
